param(
  [switch]$Build
)

# aplicar-v99-tela-operador-completa.ps1
# Cria a area completa do operador:
# /operator/dashboard
# /operator/events
# /operator/validation
# /operator/support
# /operator/reports
#
# Esta versao e segura para aplicar porque cria telas novas e aproveita
# os dados existentes de operator-assignments quando disponiveis.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

$WebDir = Join-Path $Root "apps\web"
$ComponentPath = Join-Path $Root "apps\web\src\app\operator\_components\OperatorPanel.tsx"
$HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

function Write-Utf8($Path, $Content) {
  $Dir = Split-Path $Path -Parent
  if (-not (Test-Path $Dir)) {
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
  }

  $Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $Utf8NoBom)
}

function Backup-IfExists($Path) {
  if (Test-Path $Path) {
    $Backup = "$Path.bak-v99-$Stamp"
    Copy-Item $Path $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }
}

Write-Host "Aplicando v99 - tela completa do operador..." -ForegroundColor Cyan

if (-not (Test-Path $WebDir)) {
  throw "Nao encontrei apps\web. Rode na raiz plataforma-ingressos."
}

Backup-IfExists $ComponentPath
Write-Utf8 $ComponentPath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")))
Write-Host "Criado/atualizado: apps\web\src\app\operator\_components\OperatorPanel.tsx" -ForegroundColor Green


$PagePath = Join-Path $Root "apps\web\src\app\operator\dashboard\page.tsx"
Backup-IfExists $PagePath
Write-Utf8 $PagePath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("aW1wb3J0IHsgT3BlcmF0b3JEYXNoYm9hcmRQYWdlIH0gZnJvbSAiLi4vX2NvbXBvbmVudHMvT3BlcmF0b3JQYW5lbCI7CgpleHBvcnQgZGVmYXVsdCBPcGVyYXRvckRhc2hib2FyZFBhZ2U7Cg==")))
Write-Host "Criado/atualizado: apps\web\src\app\operator\dashboard\page.tsx" -ForegroundColor Green


$PagePath = Join-Path $Root "apps\web\src\app\operator\events\page.tsx"
Backup-IfExists $PagePath
Write-Utf8 $PagePath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("aW1wb3J0IHsgT3BlcmF0b3JFdmVudHNQYWdlIH0gZnJvbSAiLi4vX2NvbXBvbmVudHMvT3BlcmF0b3JQYW5lbCI7CgpleHBvcnQgZGVmYXVsdCBPcGVyYXRvckV2ZW50c1BhZ2U7Cg==")))
Write-Host "Criado/atualizado: apps\web\src\app\operator\events\page.tsx" -ForegroundColor Green


$PagePath = Join-Path $Root "apps\web\src\app\operator\validation\page.tsx"
Backup-IfExists $PagePath
Write-Utf8 $PagePath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("aW1wb3J0IHsgT3BlcmF0b3JWYWxpZGF0aW9uUGFnZSB9IGZyb20gIi4uL19jb21wb25lbnRzL09wZXJhdG9yUGFuZWwiOwoKZXhwb3J0IGRlZmF1bHQgT3BlcmF0b3JWYWxpZGF0aW9uUGFnZTsK")))
Write-Host "Criado/atualizado: apps\web\src\app\operator\validation\page.tsx" -ForegroundColor Green


$PagePath = Join-Path $Root "apps\web\src\app\operator\support\page.tsx"
Backup-IfExists $PagePath
Write-Utf8 $PagePath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("aW1wb3J0IHsgT3BlcmF0b3JTdXBwb3J0UGFnZSB9IGZyb20gIi4uL19jb21wb25lbnRzL09wZXJhdG9yUGFuZWwiOwoKZXhwb3J0IGRlZmF1bHQgT3BlcmF0b3JTdXBwb3J0UGFnZTsK")))
Write-Host "Criado/atualizado: apps\web\src\app\operator\support\page.tsx" -ForegroundColor Green


$PagePath = Join-Path $Root "apps\web\src\app\operator\reports\page.tsx"
Backup-IfExists $PagePath
Write-Utf8 $PagePath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("aW1wb3J0IHsgT3BlcmF0b3JSZXBvcnRzUGFnZSB9IGZyb20gIi4uL19jb21wb25lbnRzL09wZXJhdG9yUGFuZWwiOwoKZXhwb3J0IGRlZmF1bHQgT3BlcmF0b3JSZXBvcnRzUGFnZTsK")))
Write-Host "Criado/atualizado: apps\web\src\app\operator\reports\page.tsx" -ForegroundColor Green


if (Test-Path $HeaderPath) {
  Backup-IfExists $HeaderPath
  $PatchHeaderPath = Join-Path $env:TEMP "v99-patch-operator-links.js"
  Write-Utf8 $PatchHeaderPath ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")))
  & node $PatchHeaderPath $HeaderPath

  if ($LASTEXITCODE -ne 0) {
    throw "Falha ao atualizar CustomerHeader."
  }
} else {
  Write-Host "CustomerHeader nao encontrado. Pulando menu." -ForegroundColor Yellow
}

if ($Build) {
  Write-Host ""
  Write-Host "Rodando build do WEB para validar..." -ForegroundColor Cyan
  Push-Location $WebDir
  & cmd.exe /d /s /c "npm run build"
  $BuildExit = $LASTEXITCODE
  Pop-Location

  if ($BuildExit -ne 0) {
    Write-Host ""
    Write-Host "A v99 foi aplicada, mas o build encontrou erro." -ForegroundColor Yellow
    Write-Host "Envie o erro completo. Nao rode scripts antigos por cima." -ForegroundColor Yellow
    exit $BuildExit
  }

  Write-Host "Build do WEB passou." -ForegroundColor Green
} else {
  Write-Host ""
  Write-Host "Build nao executado para nao bloquear por erros antigos de outras telas." -ForegroundColor Yellow
  Write-Host "Para validar depois, rode este script com -Build." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "OK FINAL v99:" -ForegroundColor Green
Write-Host "- /operator/dashboard criado." -ForegroundColor Green
Write-Host "- /operator/events criado." -ForegroundColor Green
Write-Host "- /operator/validation criado." -ForegroundColor Green
Write-Host "- /operator/support criado." -ForegroundColor Green
Write-Host "- /operator/reports criado." -ForegroundColor Green
Write-Host "- Menu do operador atualizado." -ForegroundColor Green
Write-Host ""
Write-Host "Reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
Write-Host ""
Write-Host "Abra:" -ForegroundColor Cyan
Write-Host "http://localhost:3000/operator/dashboard" -ForegroundColor Cyan
